=== FILE: tb/irq_ctrl_tb.sv ===
// Self-checking directed testbench for irq_ctrl.
// Task prj-486b52a6aa:testbench, requirement req-efb85c3b8e.
// Every expected value comes from interface_spec.md (the req tags are named per
// scenario), never from the design's own outputs. A reference model, written from
// the same spec, is also compared on every clock edge against irq, irq_id and
// rdata at all four addresses.
// Timing: inputs change about 6 ns after a rising edge; outputs are sampled 1 ns
// after the edge (period 20 ns), so the stimulus does not race the design.
`timescale 1ns / 1ps

module irq_ctrl_tb_unit #(
    parameter integer N = 8
) (
    output int passed,
    output int failed,
    output bit done
);
    localparam integer H = N - 1;   // highest-numbered source
    localparam integer M = N / 2;   // a middle source (equals H when N = 2)
    localparam logic [31:0] MASK = (N == 32) ? 32'hFFFF_FFFF : ((32'd1 << N) - 32'd1);

    logic         clk = 1'b0;
    logic         rst_n;
    logic [N-1:0] src;
    logic         we;
    logic [1:0]   addr;
    logic [31:0]  wdata;
    wire  [31:0]  rdata;
    wire          irq;
    wire  [4:0]   irq_id;

    irq_ctrl #(.N(N)) dut (
        .clk    (clk),
        .rst_n  (rst_n),
        .src    (src),
        .we     (we),
        .addr   (addr),
        .wdata  (wdata),
        .rdata  (rdata),
        .irq    (irq),
        .irq_id (irq_id)
    );

    always #10 clk = ~clk;

    // Reference model state, written from interface_spec.md section 4.
    logic [N-1:0] m_en;
    logic [N-1:0] m_mode;
    logic [N-1:0] m_pend;
    logic [N-1:0] m_srcq;   // remembered level of each source
    logic [31:0]  r;

    function automatic logic [31:0] b(input integer i);
        return 32'd1 << i;
    endfunction

    function automatic logic [N-1:0] srcv(input logic [31:0] v);
        return v[N-1:0];
    endfunction

    function automatic logic [31:0] widen(input logic [N-1:0] v);
        logic [31:0] w;
        w = 32'd0;
        w[N-1:0] = v;
        return w;
    endfunction

    // IRQ-MASK
    function automatic logic exp_irq_f(input logic [N-1:0] act);
        return |act;
    endfunction

    // IRQ-PRIORITY: lowest-numbered active source; 0 when none is active.
    function automatic logic [4:0] exp_id_f(input logic [N-1:0] act);
        logic [4:0] id;
        bit found;
        id = 5'd0;
        found = 1'b0;
        for (int k = 0; k < N; k++)
            if (!found && act[k]) begin
                id = k[4:0];
                found = 1'b1;
            end
        return id;
    endfunction

    // Register map, IRQ-PARAM (upper bits zero), IRQ-CLAIM.
    function automatic logic [31:0] exp_rdata(input logic [1:0] a);
        logic [N-1:0] act;
        act = m_pend & m_en;
        case (a)
            2'd0:    return widen(m_en);
            2'd1:    return widen(m_mode);
            2'd2:    return widen(m_pend);
            default: return {exp_irq_f(act), 26'd0, exp_id_f(act)};
        endcase
    endfunction

    task automatic check(input string what, input logic [31:0] got, input logic [31:0] exp);
        if (got === exp) begin
            passed++;
        end else begin
            failed++;
            $display("FAIL N=%0d %s: got %h expected %h (addr=%0d) at %0t",
                     N, what, got, exp, addr, $time);
        end
    endtask

    // Model update at a rising edge, from the inputs present at that edge.
    task automatic model_edge();
        logic [N-1:0] det;
        logic [N-1:0] clr;
        if (!rst_n) begin                       // IRQ-RESET
            m_en   = '0;
            m_mode = '0;
            m_pend = '0;
            m_srcq = '0;
        end else begin
            for (int k = 0; k < N; k++)         // IRQ-LEVEL, IRQ-EDGE, IRQ-DETECT-DISABLED
                det[k] = m_mode[k] ? (src[k] & ~m_srcq[k]) : src[k];
            clr = '0;
            if (we && addr == 2'd2)             // IRQ-W1C
                clr = wdata[N-1:0];
            if (we && addr == 2'd3 && wdata[4:0] < N)  // IRQ-ACK
                clr[wdata[4:0]] = 1'b1;
            m_pend = (m_pend & ~clr) | det;     // IRQ-SET-WINS
            if (we && addr == 2'd0) m_en   = wdata[N-1:0];   // IRQ-REG-RW
            if (we && addr == 2'd1) m_mode = wdata[N-1:0];
            m_srcq = src;
        end
    endtask

    // One clock edge: update the model, then compare every output, sweeping addr
    // across all four registers (IRQ-READ: a read changes nothing, no clock edge needed).
    task automatic tick();
        logic [1:0] a_save;
        @(posedge clk);
        model_edge();
        #1;
        check("model irq", {31'd0, irq}, {31'd0, exp_irq_f(m_pend & m_en)});
        check("model irq_id", {27'd0, irq_id}, {27'd0, exp_id_f(m_pend & m_en)});
        a_save = addr;
        for (int ai = 0; ai < 4; ai++) begin
            addr = ai[1:0];
            #1;
            check("model rdata sweep", rdata, exp_rdata(ai[1:0]));
        end
        addr = a_save;
        #1;
        check("model rdata at addr", rdata, exp_rdata(addr));
    endtask

    task automatic wr(input logic [1:0] a, input logic [31:0] d);
        we    = 1'b1;
        addr  = a;
        wdata = d;
        tick();
        we    = 1'b0;
        wdata = 32'd0;
    endtask

    // Directed checks against values taken from the spec.
    task automatic chk_reg(input string what, input logic [1:0] a, input logic [31:0] exp);
        we   = 1'b0;
        addr = a;
        #1;
        check(what, rdata, exp);
    endtask

    task automatic chk_irq(input string what, input logic exp_irq, input integer exp_id);
        check(what, {31'd0, irq}, {31'd0, exp_irq});
        check(what, {27'd0, irq_id}, exp_id);
    endtask

    initial begin
        passed = 0;
        failed = 0;
        done   = 1'b0;
        rst_n  = 1'b0;
        src    = '0;
        we     = 1'b0;
        addr   = 2'd0;
        wdata  = 32'd0;
        m_en   = '0;
        m_mode = '0;
        m_pend = '0;
        m_srcq = '0;

        // S0 IRQ-RESET: reset clears everything, even with every source high.
        tick();
        src = srcv(32'hFFFF_FFFF);
        tick();
        src = '0;
        chk_reg("reset ENABLE", 2'd0, 32'd0);
        chk_reg("reset MODE", 2'd1, 32'd0);
        chk_reg("reset PENDING", 2'd2, 32'd0);
        chk_reg("reset CLAIM", 2'd3, 32'd0);
        chk_irq("reset irq", 1'b0, 0);
        rst_n = 1'b1;
        tick();
        chk_reg("after reset PENDING", 2'd2, 32'd0);

        // S1 IRQ-REG-RW, IRQ-PARAM, IRQ-W1C never sets, IRQ-ACK with nothing pending.
        wr(2'd0, 32'hFFFF_FFFF);
        chk_reg("ENABLE all ones, upper bits zero", 2'd0, MASK);
        chk_reg("MODE untouched by ENABLE write", 2'd1, 32'd0);
        wr(2'd1, 32'hFFFF_FFFF);
        chk_reg("MODE all ones, upper bits zero", 2'd1, MASK);
        chk_reg("ENABLE untouched by MODE write", 2'd0, MASK);
        wr(2'd0, 32'h5A5A_A5A5);
        chk_reg("ENABLE pattern", 2'd0, 32'h5A5A_A5A5 & MASK);
        chk_reg("MODE kept", 2'd1, MASK);
        wr(2'd1, 32'hC33C_0FF0);
        chk_reg("MODE pattern", 2'd1, 32'hC33C_0FF0 & MASK);
        chk_reg("ENABLE kept", 2'd0, 32'h5A5A_A5A5 & MASK);
        chk_reg("PENDING untouched", 2'd2, 32'd0);
        wr(2'd2, 32'hFFFF_FFFF);
        chk_reg("PENDING write never sets", 2'd2, 32'd0);
        chk_irq("nothing pending", 1'b0, 0);
        wr(2'd3, 32'd0);
        chk_reg("ack with nothing pending", 2'd2, 32'd0);
        chk_reg("ack leaves ENABLE", 2'd0, 32'h5A5A_A5A5 & MASK);
        wr(2'd0, 32'd0);
        wr(2'd1, 32'd0);
        chk_reg("ENABLE cleared", 2'd0, 32'd0);
        chk_reg("MODE cleared", 2'd1, 32'd0);

        // S2 IRQ-DETECT-DISABLED, IRQ-LEVEL, IRQ-MASK, IRQ-CLAIM.
        src = srcv(b(H));
        tick();
        src = '0;
        chk_reg("disabled source pends", 2'd2, b(H));
        chk_irq("disabled source does not interrupt", 1'b0, 0);
        chk_reg("CLAIM while masked", 2'd3, 32'd0);
        tick();
        chk_reg("pending is sticky", 2'd2, b(H));
        wr(2'd0, b(H));
        chk_irq("enable unmasks", 1'b1, H);
        chk_reg("CLAIM names highest source", 2'd3, 32'h8000_0000 | H);
        wr(2'd2, b(H));
        chk_reg("W1C clears", 2'd2, 32'd0);
        chk_irq("cleared", 1'b0, 0);
        chk_reg("CLAIM after clear", 2'd3, 32'd0);
        chk_reg("ENABLE kept after W1C", 2'd0, b(H));

        // S3 IRQ-LATENCY: no path from src to irq; irq changes at the detecting and ack edges.
        src = srcv(b(H));
        #1;
        chk_irq("no irq before the detecting edge", 1'b0, 0);
        tick();
        src = '0;
        chk_irq("irq at detection edge", 1'b1, H);
        wr(2'd3, H);
        chk_irq("irq drops at ack edge", 1'b0, 0);
        chk_reg("ack cleared", 2'd2, 32'd0);

        // S4 IRQ-PRIORITY and IRQ-ACK with several requesters.
        wr(2'd0, MASK);
        src = srcv(b(H) | b(M));
        tick();
        src = '0;
        chk_reg("two pending", 2'd2, b(H) | b(M));
        chk_irq("lower number wins", 1'b1, M);
        src = srcv(b(0));
        tick();
        src = '0;
        chk_irq("source 0 wins", 1'b1, 0);
        chk_reg("CLAIM source 0", 2'd3, 32'h8000_0000);
        wr(2'd3, 32'd0);
        chk_reg("ack clears source 0 only", 2'd2, b(H) | b(M));
        chk_irq("next in priority", 1'b1, M);
        src = srcv(b(0));            // detected at the same edge the ENABLE write lands
        wr(2'd0, b(H));
        src = '0;
        chk_reg("three pending", 2'd2, b(0) | b(M) | b(H));
        chk_irq("disabled lower source loses", 1'b1, H);
        chk_reg("CLAIM highest enabled", 2'd3, 32'h8000_0000 | H);
        wr(2'd0, MASK);
        chk_irq("re-enabled source 0 wins", 1'b1, 0);
        if (N < 32) begin
            wr(2'd3, N);
            chk_reg("ack number N changes nothing", 2'd2, b(0) | b(M) | b(H));
            wr(2'd3, 32'd31);
            chk_reg("ack number 31 changes nothing", 2'd2, b(0) | b(M) | b(H));
        end
        wr(2'd3, 32'hFFFF_FFE0);
        chk_reg("ack uses bits 4..0 only", 2'd2, b(M) | b(H));
        chk_irq("after ack 0", 1'b1, M);
        wr(2'd3, H);
        chk_reg("ack highest source", 2'd2, (b(M) | b(H)) & ~b(H));
        chk_irq("after ack H", (M != H), (M != H) ? M : 0);
        wr(2'd2, MASK);
        chk_reg("all cleared", 2'd2, 32'd0);
        chk_irq("idle", 1'b0, 0);

        // S5 IRQ-W1C: clears exactly the bits written 1.
        src = srcv(b(0) | b(1) | b(H));
        tick();
        src = '0;
        chk_reg("three pending for W1C", 2'd2, b(0) | b(1) | b(H));
        wr(2'd2, 32'hAAAA_AAAA);
        chk_reg("W1C clears odd bits only", 2'd2, (b(0) | b(1) | b(H)) & ~32'hAAAA_AAAA);
        chk_irq("source 0 left", 1'b1, 0);
        wr(2'd2, 32'd0);
        chk_reg("W1C of zero changes nothing", 2'd2, (b(0) | b(1) | b(H)) & ~32'hAAAA_AAAA);
        wr(2'd2, 32'h5555_5555);
        chk_reg("W1C clears even bits", 2'd2, 32'd0);

        // S6 IRQ-SET-WINS, level source held high.
        src = srcv(b(M));
        tick();
        chk_reg("level source pends", 2'd2, b(M));
        wr(2'd2, b(M));
        chk_reg("W1C loses to level detection", 2'd2, b(M));
        chk_irq("still interrupting", 1'b1, M);
        wr(2'd3, M);
        chk_reg("ack loses to level detection", 2'd2, b(M));
        src = '0;
        wr(2'd3, M);
        chk_reg("ack after release clears", 2'd2, 32'd0);
        chk_irq("released", 1'b0, 0);

        // S7 IRQ-EDGE, IRQ-SET-WINS, edge source.
        wr(2'd1, b(M));
        chk_reg("MODE edge for M", 2'd1, b(M));
        src = srcv(b(M));
        tick();
        chk_reg("rising edge pends", 2'd2, b(M));
        chk_irq("edge source interrupts", 1'b1, M);
        tick();
        chk_reg("held high stays pending", 2'd2, b(M));
        wr(2'd2, b(M));
        chk_reg("held high edge source clears", 2'd2, 32'd0);
        chk_irq("edge cleared", 1'b0, 0);
        tick();
        chk_reg("held high sets only once", 2'd2, 32'd0);
        src = '0;
        tick();
        chk_reg("falling edge sets nothing", 2'd2, 32'd0);
        src = srcv(b(M));
        wr(2'd2, b(M));
        chk_reg("rising edge wins over W1C", 2'd2, b(M));
        src = '0;
        wr(2'd3, M);
        chk_reg("ack clears edge source", 2'd2, 32'd0);
        src = srcv(b(M));
        tick();
        chk_reg("second rising edge pends", 2'd2, b(M));
        wr(2'd3, M);
        chk_reg("ack while held clears edge source", 2'd2, 32'd0);
        src = '0;
        tick();
        wr(2'd1, 32'd0);

        // S8 IRQ-EDGE: the remembered level is tracked in level mode too.
        src = srcv(b(H));
        tick();
        tick();
        chk_reg("level source held pends", 2'd2, b(H));
        wr(2'd1, b(H));
        chk_reg("MODE now edge for H", 2'd1, b(H));
        chk_reg("still pending after mode write", 2'd2, b(H));
        wr(2'd2, b(H));
        chk_reg("no edge after switching while high", 2'd2, 32'd0);
        tick();
        chk_reg("still no edge", 2'd2, 32'd0);
        chk_irq("no interrupt", 1'b0, 0);
        src = '0;
        tick();
        wr(2'd1, 32'd0);

        // S9 IRQ-RESET in the middle of operation.
        wr(2'd1, b(M));
        src = srcv(b(0) | b(M));
        tick();
        chk_reg("pending before reset", 2'd2, b(0) | b(M));
        chk_irq("interrupt before reset", 1'b1, 0);
        rst_n = 1'b0;
        tick();
        chk_reg("mid reset ENABLE", 2'd0, 32'd0);
        chk_reg("mid reset MODE", 2'd1, 32'd0);
        chk_reg("mid reset PENDING", 2'd2, 32'd0);
        chk_irq("mid reset irq", 1'b0, 0);
        tick();
        chk_reg("reset wins over high sources", 2'd2, 32'd0);
        rst_n = 1'b1;
        tick();
        chk_reg("level detection after reset", 2'd2, b(0) | b(M));
        chk_irq("masked after reset", 1'b0, 0);
        src = '0;
        wr(2'd2, MASK);
        chk_reg("cleared after reset test", 2'd2, 32'd0);

        // S10 random traffic with rare resets, checked by the model on every edge.
        for (int c = 0; c < 400; c++) begin
            r     = $random;
            rst_n = (r[11:6] != 6'd0);
            src   = srcv($random & $random & $random);
            we    = r[0];
            addr  = r[3:2];
            wdata = $random;
            if (addr == 2'd3 && r[4])
                wdata[4:0] = wdata[4:0] % N;
            tick();
        end

        rst_n = 1'b1;
        we    = 1'b0;
        src   = '0;
        tick();
        done = 1'b1;
    end
endmodule

module irq_ctrl_tb;
    int    p8, f8, p2, f2, p32, f32;
    bit    d8, d2, d32;
    string nonce;
    bit    got;
    int    total_p, total_f;

    irq_ctrl_tb_unit #(.N(8))  u_n8  (.passed(p8),  .failed(f8),  .done(d8));
    irq_ctrl_tb_unit #(.N(2))  u_n2  (.passed(p2),  .failed(f2),  .done(d2));
    irq_ctrl_tb_unit #(.N(32)) u_n32 (.passed(p32), .failed(f32), .done(d32));

    initial begin
        nonce = "";
        got = $value$plusargs("NIRMAAN_NONCE=%s", nonce);
        if (!got) got = $value$plusargs("nirmaan_nonce=%s", nonce);
        if (!got) got = $value$plusargs("NONCE=%s", nonce);
        if (!got) got = $value$plusargs("nonce=%s", nonce);
        wait (d8 && d2 && d32);
        #1;
        total_p = p8 + p2 + p32;
        total_f = f8 + f2 + f32;
        if (!got) begin
            $display("ERROR: no nonce plusarg found");
            nonce = "MISSING";
            total_f = total_f + 1;
        end
        $display("unit N=8:  pass=%0d fail=%0d", p8, f8);
        $display("unit N=2:  pass=%0d fail=%0d", p2, f2);
        $display("unit N=32: pass=%0d fail=%0d", p32, f32);
        $display("NIRMAAN-SIM %s %0d passed, %0d failed", nonce, total_p, total_f);
        $finish;
    end

    initial begin
        #5_000_000;
        $display("ERROR: timeout before all units finished");
        if (!got) nonce = "MISSING";
        $display("NIRMAAN-SIM %s %0d passed, %0d failed", nonce,
                 p8 + p2 + p32, f8 + f2 + f32 + 1);
        $finish;
    end
endmodule
=== END FILE ===
